uint32_t AntialiasAlpha(uint32_t radius, uint32_t distance)
{
    constexpr uint32_t kThinLimit = 62, kReach = 14, kInner = 14;
    if (radius == 0 || distance > radius + kReach)
        return 0;
    if (radius < kThinLimit)
        return kThinAlpha[kThinOffsets[radius - 1] + distance];
    if (distance + kInner <= radius)
        return kChannelMax;
    return kEdgeAlpha[radius + kReach - distance];
}

